// GF(2^8) arithmetic over the Rijndael polynomial x^8+x^4+x^3+x+1 = 0x11b,
// as required by EIP-3450 and the AES standard.
//
// The prior implementation used the `gf256` crate's default type, which uses
// the polynomial 0x11d instead of the EIP-3450 required 0x11b. This caused
// shares generated by this tool to be incompatible with any other compliant
// EIP-3450 implementation.

use std::ops::{Add, AddAssign, Div, Mul, MulAssign};

use rand::{CryptoRng, Rng, RngCore};

use crate::shamir::{Random, ShamirPolynomial, ShamirSecretSharing, ShamirShare, Zero};

/// An element of GF(2^8) reduced by the Rijndael polynomial 0x11b (EIP-3450 / AES compliant).
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct gf256(pub u8);

/// Multiply two GF(2^8) elements using the Rijndael polynomial x^8+x^4+x^3+x+1 = 0x11b.
#[inline(always)]
fn gf_mul(mut a: u8, mut b: u8) -> u8 {
    let mut result = 0u8;
    for _ in 0..8 {
        if b & 1 != 0 {
            result ^= a;
        }
        let carry = a & 0x80;
        a <<= 1;
        if carry != 0 {
            a ^= 0x1b; // x^8 mod 0x11b — the low 8 bits of the reducing polynomial
        }
        b >>= 1;
    }
    result
}

/// Compute the multiplicative inverse of `b` in GF(2^8) via Fermat's little theorem:
/// b^(-1) = b^(254) since |GF(2^8)*| = 255.
#[inline]
fn gf_inv(b: u8) -> u8 {
    debug_assert!(b != 0, "gf division by zero");
    let mut result = 1u8;
    let mut base = b;
    let mut exp = 254u32;
    while exp > 0 {
        if exp & 1 != 0 {
            result = gf_mul(result, base);
        }
        base = gf_mul(base, base);
        exp >>= 1;
    }
    result
}

impl Add for gf256 {
    type Output = Self;
    #[inline]
    fn add(self, rhs: Self) -> Self {
        gf256(self.0 ^ rhs.0)
    }
}

impl AddAssign for gf256 {
    #[inline]
    fn add_assign(&mut self, rhs: Self) {
        self.0 ^= rhs.0;
    }
}

impl Mul for gf256 {
    type Output = Self;
    #[inline]
    fn mul(self, rhs: Self) -> Self {
        gf256(gf_mul(self.0, rhs.0))
    }
}

impl MulAssign for gf256 {
    #[inline]
    fn mul_assign(&mut self, rhs: Self) {
        self.0 = gf_mul(self.0, rhs.0);
    }
}

impl Div for gf256 {
    type Output = Self;
    #[inline]
    fn div(self, rhs: Self) -> Self {
        assert!(rhs.0 != 0, "gf division by zero");
        gf256(gf_mul(self.0, gf_inv(rhs.0)))
    }
}

impl From<u8> for gf256 {
    fn from(v: u8) -> Self {
        gf256(v)
    }
}

impl From<gf256> for u8 {
    fn from(v: gf256) -> u8 {
        v.0
    }
}

impl Zero for gf256 {
    fn zero() -> Self {
        gf256(0)
    }
}

impl Random for gf256 {
    fn random<R: CryptoRng + RngCore>(rng: &mut R) -> Self {
        // Use the full range 0..=255 for a uniform distribution over GF(2^8).
        // The prior implementation used 1..=255, which incorrectly excluded 0
        // and biased polynomial coefficients.
        gf256(rng.random_range(0..=255))
    }
}

impl ShamirSecretSharing for gf256 {
    fn split<R: CryptoRng + RngCore>(&self, n: u8, t: u8, rng: &mut R) -> Vec<ShamirShare<Self>> {
        assert!(n > 0, "There must be at least one share");
        // t=1 is not a meaningful secret sharing scheme: all shares equal the secret.
        // EIP-3450 requires t > 1.
        assert!(t > 1, "The threshold must be at least two for meaningful secret sharing");
        assert!(t <= n, "The threshold must be lower than the total shares");

        let polynomial = ShamirPolynomial::random(*self, t - 1, rng);

        (1..=n)
            .map(|id| {
                let secret = polynomial.evaluate(gf256(id));
                ShamirShare::new(id, secret)
            })
            .collect()
    }

    fn reconstruct<S: AsRef<ShamirShare<Self>>>(shares: &[S]) -> Self {
        // Validate that all share IDs are distinct before interpolation.
        // Duplicate IDs produce a zero denominator in Lagrange interpolation,
        // causing a division-by-zero panic.
        let mut ids: Vec<u8> = shares
            .iter()
            .map(|s| *s.as_ref().as_coordinates().0)
            .collect();
        ids.sort_unstable();
        assert!(
            ids.windows(2).all(|w| w[0] != w[1]),
            "Shamir reconstruct: duplicate share IDs provided — shares must be distinct"
        );

        let mut y = gf256(0);
        for (i, share) in shares.iter().enumerate() {
            let mut li = gf256(1);
            let (x0, y0) = share.as_ref().as_coordinates();
            for (j, share) in shares.iter().enumerate() {
                let (x1, _y1) = share.as_ref().as_coordinates();
                if i != j {
                    li *= gf256(*x1) / (gf256(*x0) + gf256(*x1));
                }
            }
            y += li * *y0;
        }
        y
    }
}

/// NOTE: No chaos test is implemented for the group GF(256) because the field is too small
/// to prevent collisions.
#[cfg(test)]
mod test {
    use crate::gf256::gf256;

    use crate::shamir;

    #[test]
    fn reconstruct() {
        shamir::test::test_reconstruct::<gf256>();
    }

    #[test]
    fn reconstruct_sparse() {
        shamir::test::test_reconstruct_sparse::<gf256>();
    }

    #[test]
    fn reconstruct_missing_shares() {
        shamir::test::test_reconstruct_missing_shares::<gf256>();
    }

    #[test]
    fn polynomial_uses_rijndael_0x11b() {
        // Verify that GF(256) arithmetic matches the AES/Rijndael standard (0x11b),
        // not the previously used 0x11d polynomial.
        //
        // Test vectors from FIPS-197 (AES specification):
        //   0x02 * 0x87 = 0x15  (xtime(0x87) in AES)
        //   0x57 * 0x83 = 0xc1  (FIPS-197 Appendix B MixColumns example)
        let test_vectors: &[(u8, u8, u8)] = &[
            (0x02, 0x87, 0x15),
            (0x57, 0x83, 0xc1),
        ];
        for &(a, b, expected) in test_vectors {
            let result = (gf256(a) * gf256(b)).0;
            assert_eq!(
                result, expected,
                "GF multiply {a:#04x} * {b:#04x}: got {result:#04x}, expected {expected:#04x} (FIPS-197)"
            );
        }
    }
}
